<script lang="ts">
    import type { Component, Snippet } from "svelte";
    import type { RenderFn } from "../types.js";
    import Icon from "./Icon.svelte";

    let {
        text,
        snippet,
        render,
        component: Comp,
        props,
        icon
    }: {
        text?: string;
        snippet?: Snippet;
        render?: RenderFn;
        component?: Component;
        props?: any;
        icon?: string | Component;
    } = $props();
</script>

{#if icon}
    <Icon {icon} alt={text} />
{/if}
{#if text}
    <span class="text">{text}</span>
{/if}
{#if snippet}
    {@render snippet()}
{:else if render}
    {@render render()}
{/if}
{#if Comp}
    <Comp {...props} />
{/if}
